def apply_one(path, marker, hunks):
    with io.open(path, encoding="utf-8-sig", newline="") as f:
        src = f.read()
    if marker in src:
        print("  already patched: %s" % os.path.basename(path))
        return False
    new = src
    for tag, lineno, anchor, repl in hunks:
        n = new.count(anchor)
        if n != 1:
            raise SystemExit("  anchor count=%d (expect 1) at %s near line %d"
                             % (n, os.path.basename(path), lineno))
        new = new.replace(anchor, repl)
    with io.open(path, "w", encoding="utf-8", newline="") as f:
        f.write(new)
    print("  patched %s (%d hunks)" % (os.path.basename(path), len(hunks)))
    return True


def main():
    import py_compile
    for rel, marker, hunks in PATCHES:
        apply_one(os.path.join(REPO, rel.replace("/", os.sep)), marker, hunks)
    for rel, _marker, _hunks in PATCHES:
        py_compile.compile(os.path.join(REPO, rel.replace("/", os.sep)), doraise=True)
    print("py_compile OK")
    return 0


if __name__ == "__main__":
    sys.exit(main())
